// README example, copied literally; only `page` and `tokens` are supplied, as the README assumes.
import { chromium } from 'playwright';
import { it } from 'vitest';
import { KIT_RULES, grade, receipt, receiptText, repairPlan, designId } from '@refraction/kit';
import * as checks from '@refraction/kit/src/page-checks/index.js';

it('README example', async () => {
  const browser = await chromium.launch(process.env.PW_CHROMIUM ? { executablePath: process.env.PW_CHROMIUM } : {});
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('file://' + process.cwd() + '/packages/kit/fixtures/good.html');
  const tokens = { '--ink': '#1a1a1a', '--paper': '#ffffff', '--accent': '#0b5fff', '--line': '#d0d5dd', '--radius': '8px', '--radius-in': '4px', '--font-body': 'serif' };
const findings = [];
for (const fn of Object.keys(checks)) {
  if (fn === 'noSidewaysScroll') await page.setViewportSize({ width: 320, height: 800 });
  const more = fn === 'tokenFit' ? `, ${JSON.stringify(tokens)}` : '';
  findings.push(...await page.evaluate(`(${checks[fn]})(document${more})`));
  if (fn === 'noSidewaysScroll') await page.setViewportSize({ width: 1280, height: 800 });
}
  console.log(JSON.stringify(grade(findings, KIT_RULES)));
  console.log(JSON.stringify(repairPlan([findings], KIT_RULES)).slice(0, 600));
  console.log(receiptText(receipt(findings, KIT_RULES)));
  console.log(designId(tokens));
  await browser.close();
}, 120000);

