--- usr/run.e2e.ts ---
// Runs named page checks on every usr/pages/*.html. First line of each page: <!-- checks: a,b | tokens: {...} | width: 320 -->
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { chromium } from 'playwright';
import { it } from 'vitest';
import * as checks from '@refraction/kit/src/page-checks/index.js';
const C = checks as unknown as Record<string, unknown>;
it('pages', async () => {
  const browser = await chromium.launch(process.env.PW_CHROMIUM ? { executablePath: process.env.PW_CHROMIUM } : {});
  const out: string[] = [];
  const only = process.env.ONLY ?? '';
  for (const file of readdirSync('usr/pages').filter((f) => f.endsWith('.html') && f.includes(only)).sort()) {
    const head = readFileSync('usr/pages/' + file, 'utf8').split('\n')[0] ?? '';
    const names = (/checks: ([^|]*?)\s*(\||-->)/.exec(head)?.[1] ?? '').split(',').map((s) => s.trim()).filter(Boolean);
    const tokens = /tokens: (\{.*?\})\s*(\||-->)/.exec(head)?.[1] ?? '{}';
    const width = Number(/width: (\d+)/.exec(head)?.[1] ?? 1280);
    const page = await browser.newPage();
    await page.setViewportSize({ width, height: 800 });
    await page.goto('file://' + process.cwd() + '/usr/pages/' + file, { waitUntil: 'load' });
    await page.waitForTimeout(300);
    for (const fn of names) {
      if (fn === 'noSidewaysScroll') await page.setViewportSize({ width: 320, height: 800 });
      let res: unknown;
      try { res = C[fn] ? await page.evaluate(`(${String(C[fn])})(document${fn === 'tokenFit' ? `, ${tokens}` : ''})`) : 'NO SUCH CHECK'; } catch (e) { res = 'THREW ' + String(e).slice(0, 200); }
      if (fn === 'noSidewaysScroll') await page.setViewportSize({ width, height: 800 });
      out.push(`${file} :: ${fn} :: ${JSON.stringify(res)}`);
    }
    await page.close();
  }
  await browser.close();
  writeFileSync(process.env.OUT ?? 'usr/out.txt', out.join('\n') + '\n');
}, 600000);

